      const genderRaw = String(pp?.gender ?? pp?.sex ?? "").toUpperCase();
      const gender = (genderRaw === "F" || genderRaw === "FEMALE" || genderRaw === "W" || genderRaw === "WOMEN") ? "F" : "M";
      const groupKey = teeLabel || gender;
