    if (!ordered.length) return { ok: false, reason: "no_valid", targetCourse, targetTee };

    const best = ordered[0];
    const worst = ordered[ordered.length - 1];
    const gap = Number(best[1].avgDelta) - Number(worst[1].avgDelta);

    let favours = "neutral";
